const token = $('获取飞书Token').first().json.tenant_access_token;
const baseId = $env.FEISHU_BASE_ID || 'Y2ZgbUGWqa0MB4sLmXxc89T5n0P';
const tableId = 'tbl4vQ8kft1XXSLv';
const viewId = 'vewjGvlbFc';
const first = $json;

if (first.code !== 0 && first.code !== undefined) {
  throw new Error(`拉取供应商表失败: ${first.msg || JSON.stringify(first)}`);
}

const searchBody = {
  view_id: viewId,
  field_names: ['供应商', '户名', '开户支行', '银行名称', '类型', '地域', '资质', 'AI 标记'],
};

function pickText(field) {
  if (field == null) return '';
  if (typeof field === 'string') return field.trim();
  if (typeof field === 'number') return String(field);
  if (Array.isArray(field)) {
    if (!field.length) return '';
    const first = field[0];
    if (typeof first === 'string') return first.trim();
    if (first && typeof first.text === 'string') return first.text.trim();
    return pickText(first);
  }
  if (typeof field === 'object') {
    if (Array.isArray(field.value) && field.value.length) return pickText(field.value);
    if (typeof field.text === 'string') return field.text.trim();
  }
  return '';
}

const records = [...(first.data?.items || [])];
let pageToken = first.data?.page_token || '';
let hasMore = Boolean(first.data?.has_more);

while (hasMore && pageToken) {
  const qs = new URLSearchParams({ page_size: '500', page_token: pageToken });
  const url = `https://open.feishu.cn/open-apis/bitable/v1/apps/${baseId}/tables/${tableId}/records/search?${qs}`;
  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url,
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: searchBody,
    json: true,
  });
  if (resp.code !== 0) {
    throw new Error(`供应商表翻页失败: ${resp.msg || JSON.stringify(resp)}`);
  }
  records.push(...(resp.data?.items || []));
  hasMore = Boolean(resp.data?.has_more);
  pageToken = resp.data?.page_token || '';
  if (!hasMore) break;
}

return records
  .filter((r) => r && r.record_id)
  .map((r) => {
    const f = r.fields || {};
    return {
      json: {
        record_id: r.record_id,
        供应商: pickText(f['供应商']),
        户名: pickText(f['户名']),
        开户支行: pickText(f['开户支行']),
        银行名称: pickText(f['银行名称']),
        类型: pickText(f['类型']) || null,
        地域: pickText(f['地域']) || null,
        资质: pickText(f['资质']) || null,
        fields: {
          类型: pickText(f['类型']),
          地域: pickText(f['地域']),
          资质: pickText(f['资质']),
        },
      },
    };
  });

const items = $input.all().map((i) => i.json).filter((j) => j && j.record_id);
const batch = items.map((j, index) => ({
  index,
  record_id: j.record_id,
  供应商: j.供应商 || '',
  户名: j.户名 || '',
  开户支行: j.开户支行 || '',
  银行名称: j.银行名称 || '',
  类型: j.类型,
  地域: j.地域,
  资质: j.资质,
  fields: j.fields || {
    类型: j.类型 || '',
    地域: j.地域 || '',
    资质: j.资质 || '',
  },
}));

// AI 输入不含 record_id，按 index 对齐
const aiPayload = batch.map((b) => ({
  index: b.index,
  供应商: b.供应商,
  户名: b.户名,
  开户支行: b.开户支行,
  银行名称: b.银行名称,
  类型: b.类型,
  地域: b.地域,
  资质: b.资质,
}));

return [{
  json: {
    batch,
    batch_size: batch.length,
    ai_prompt: JSON.stringify(aiPayload, null, 2),
  },
}];

const prep = $('组装AI输入').first().json;
const batch = prep.batch || [];

const TYPE_NORMALIZE = { '景区（基地）': '景区 (基地)', '景区 (基地)': '景区 (基地)' };
const TYPE_WHITELIST = new Set(['酒店','民宿','其它','车队','景区 (基地)','景区（基地）','餐厅','客户退款','地接','导游','内部','广告搭建']);
const QUAL_WHITELIST = new Set(['旅行社','其他','餐饮','个人']);
const REGION_PREFERRED = new Set(['舟山','安吉','德清','嘉兴','金华','苏州','桐庐','上海崇明区','上海奉贤区','上海青浦区','千岛湖','杭州','湖州','上海','绍兴']);

function pickText(field) {
  if (field == null) return '';
  if (typeof field === 'string') return field.trim();
  if (typeof field === 'number') return String(field);
  if (Array.isArray(field)) {
    if (!field.length) return '';
    const first = field[0];
    if (typeof first === 'string') return first.trim();
    if (first && typeof first.text === 'string') return first.text.trim();
    return pickText(first);
  }
  if (typeof field === 'object') {
    if (Array.isArray(field.value) && field.value.length) return pickText(field.value);
    if (typeof field.text === 'string') return field.text.trim();
  }
  return '';
}

function normalizeType(value) {
  const v = String(value || '').trim();
  if (!v) return '';
  if (TYPE_NORMALIZE[v]) return TYPE_NORMALIZE[v];
  return TYPE_WHITELIST.has(v) ? v : '';
}
function normalizeQual(value) {
  const v = String(value || '').trim();
  return QUAL_WHITELIST.has(v) ? v : '';
}
function normalizeRegion(value) {
  return String(value || '').trim();
}

function buildUpdateForRecord(existing, ai) {
  const curType = pickText(existing['类型']);
  const curRegion = pickText(existing['地域']);
  const curQual = pickText(existing['资质']);
  const fields = {};
  const reviewParts = [];
  const reasons = [];
  const low = new Set(Array.isArray(ai.low_confidence) ? ai.low_confidence.map((x) => String(x).trim()).filter(Boolean) : []);

  if (!curType) {
    const t = normalizeType(ai['类型']);
    if (t) { fields['类型'] = t; if (low.has('类型')) reviewParts.push('类型'); }
    else { reasons.push('类型无法写入'); reviewParts.push('类型'); }
  }
  if (!curRegion) {
    const r = normalizeRegion(ai['地域']);
    if (r) { fields['地域'] = r; if (low.has('地域') || !REGION_PREFERRED.has(r)) reviewParts.push('地域'); }
    else { reasons.push('地域为空'); reviewParts.push('地域'); }
  }
  if (!curQual) {
    const q = normalizeQual(ai['资质']);
    if (q) { fields['资质'] = q; if (low.has('资质')) reviewParts.push('资质'); }
    else { reasons.push('资质无法写入'); reviewParts.push('资质'); }
  }

  const uniqueReview = [...new Set(reviewParts)];
  const aiMark = uniqueReview.length ? `AI 待核：${uniqueReview.join('/')}` : null;
  if (aiMark) fields['AI 标记'] = aiMark;
  const hasBusiness = fields['类型'] != null || fields['地域'] != null || fields['资质'] != null;
  return { fields, aiMark, skipped: !hasBusiness && !aiMark, reasons };
}

function parseAiBatch(raw) {
  const text = String(raw ?? '').replace(/```json/gi, '').replace(/```/g, '').trim();
  const start = text.indexOf('[');
  const end = text.lastIndexOf(']');
  if (start < 0 || end <= start) throw new Error('AI 输出不是 JSON 数组');
  const data = JSON.parse(text.slice(start, end + 1));
  if (!Array.isArray(data)) throw new Error('AI 输出根节点不是数组');
  return data;
}

const raw = $json.output ?? $json.text ?? $json.response ?? '';
let aiItems = [];
const errors = [];
try {
  aiItems = parseAiBatch(raw);
} catch (e) {
  return [{
    json: {
      has_updates: false,
      updates: [],
      errors: [{ error: String(e.message || e) }],
      raw: String(raw).slice(0, 2000),
    },
  }];
}

const updates = [];
for (let i = 0; i < batch.length; i += 1) {
  const rec = batch[i];
  const ai = aiItems[i];
  if (!ai || typeof ai !== 'object') {
    errors.push({ record_id: rec.record_id, index: i, error: 'AI 未返回该下标结果' });
    continue;
  }
  const result = buildUpdateForRecord(rec.fields || {}, ai);
  if (result.skipped) {
    errors.push({ record_id: rec.record_id, index: i, error: '无可写字段', reasons: result.reasons });
    continue;
  }
  // record_id 只来自原 item
  updates.push({
    record_id: rec.record_id,
    fields: result.fields,
  });
}

if (aiItems.length !== batch.length) {
  errors.push({ error: `AI 条数 ${aiItems.length} 与本批 ${batch.length} 不一致` });
}

return [{
  json: {
    has_updates: updates.length > 0,
    updates,
    update_count: updates.length,
    errors,
  },
}];
